MT.build = function(id){
  const c=MT.recipes.find(r=>r.id===id); if(!c || id==='r1' || !MT.details[id]) return JSON.parse(JSON.stringify(MT.full));
  const d=MT.details[id]; const unFr=v=>({'½':.5,'¼':.25,'¾':.75}[v]??+v);
  const ingredients=d.i.map((s,n)=>{const [name,a,unit,k]=s.split('|');return {id:'i'+(n+1),name,amount:unFr(a),unit,k};});
  const steps=d.s.map(s=>{const [t,tm]=s.split('|');const ids=ingredients.filter(i=>i.name.split(' ').some(w=>w.length>2&&t.includes(w.replace(/ים$|ות$/,'')))).map(i=>i.id);return {t,ids:ids.length?ids:[ingredients[0].id],timer:tm?+tm:null};});
  return {...c, serv:c.serv, ingredients, steps};
};
